// src/pages/api/lead.ts
// Handles primary lead/inquiry form submissions, routed per `intent`.
// DO NOT edit this file per client — update src/lib/email.config.ts instead.

import type { APIRoute } from 'astro';
import { Resend } from 'resend';
import { EMAIL_CONFIG } from '~/lib/email.config';
import { sendWithAlert, notifySubmission, honeypotValue } from '~/lib/form-alert';
import { addToPipedrive, type PipedriveOutcome } from '~/lib/pipedrive';
import { isResidentRole } from '~/lib/roles';
import { upsertMailchimpContact } from '~/lib/mailchimp';

const resend = new Resend(import.meta.env.RESEND_API_KEY);
// Astro reads env via import.meta.env, so pass the Slack URL explicitly.
// Slack destination. FORM_SLACK_WEBHOOK is this client's own channel and takes
// precedence for BOTH submissions and failures; FORM_ALERT_SLACK_URL is the
// shared fallback for clients without a channel of their own.
const SLACK_WEBHOOK =
  import.meta.env.FORM_SLACK_WEBHOOK || import.meta.env.FORM_ALERT_SLACK_URL;

// The form's structured per-intent answers (`fieldsJson`: a labeled, ordered
// list). Malformed input yields an empty list rather than an error.
function parseFields(raw: FormDataEntryValue | null): { label: string; value: string }[] {
  try {
    const parsed = JSON.parse(raw?.toString() ?? '[]');
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((f) => f && typeof f.label === 'string')
      .map((f) => ({ label: String(f.label), value: String(f.value ?? '').trim() }));
  } catch {
    return [];
  }
}

export const POST: APIRoute = async ({ request }) => {
  try {
    const data     = await request.formData();
    const name    = data.get('name')?.toString().trim()    ?? '';
    const email   = data.get('email')?.toString().trim()   ?? '';
    const phone   = data.get('phone')?.toString().trim()   ?? '';
    const company = data.get('company')?.toString().trim() ?? '';
    const source  = data.get('source')?.toString().trim()  ?? '';
    const intent  = data.get('intent')?.toString().trim()  ?? '';
    const ref     = data.get('ref')?.toString().trim()     ?? '';
    const message = data.get('message')?.toString().trim() ?? '';
    // stage: 'partial' = multi-step form's contact step was completed but the form
    // isn't finished yet (capture the lead now); 'complete' (default) = full submit.
    const stage     = data.get('stage')?.toString().trim() ?? 'complete';
    const isPartial = stage === 'partial';

    // Per-intent content (subject + submitter confirmation) — see email.config.ts.
    const intentCfg = EMAIL_CONFIG.intents[intent] ?? EMAIL_CONFIG.intents.default;
    const detailFields = parseFields(data.get('fieldsJson'));
    // The wizard's step-1 role ("Board President", "Property owner / resident"…).
    // Shown in the Slack heading for partials so board members and residents can
    // be told apart at a glance, and used below to keep residents out of Pipedrive.
    const leadRole = detailFields.find((f) => /role/i.test(f.label))?.value || '';

    // The Slack record: every answer, labelled, in the same order as the email.
    // Used for the normal log, the "not delivered" fallback, and the honeypot
    // discard below — so no copy of a submission is ever missing the community
    // details (it used to log only name/email/phone, because the answers travel
    // in `fieldsJson` and that key was skipped as machine data).
    const slackRows: Array<[string, string]> = [
      ['Name', name], ['Email', email], ['Phone', phone], ['Company', company],
      ...detailFields.map((f): [string, string] => [f.label, f.value]),
      ['Message', message], ['Ref', ref], ['Intent', intent], ['Stage', stage], ['Source', source],
    ];

    // Honeypot filled → a bot, or a browser / password-manager autofill that took
    // the hidden field for a contact field. Nothing is sent either way (the bot
    // must not learn it was caught), but the discard is logged to Slack with the
    // answers, so a real person caught by autofill is visible and recoverable
    // instead of silently gone while their screen said "You're all set".
    const honeypot = honeypotValue(data);
    if (honeypot) {
      await notifySubmission({
        client: EMAIL_CONFIG.brand.name,
        slackWebhookUrl: SLACK_WEBHOOK,
        route: `${intentCfg.label}${isPartial ? ' (started)' : ''} — discarded`,
        formName: `${intent || 'lead'} form`,
        status: 'discarded',
        note: `value: ${JSON.stringify(honeypot.slice(0, 60))}`,
        fields: slackRows,
      });
      return new Response(JSON.stringify({ success: true }), { status: 200 });
    }

    if (!email || !name) {
      return new Response(JSON.stringify({ error: 'Name and email are required.' }), { status: 400 });
    }

    // Route the notification to the right inbox by intent (falls back to default).
    const notifyTo = EMAIL_CONFIG.routes[intent] ?? EMAIL_CONFIG.notify;
    // Visible CC, per intent (vendor/general skip Jeff — see email.config.ts).
    const notifyCc = EMAIL_CONFIG.notifyCcByIntent[intent] ?? EMAIL_CONFIG.notifyCc;

    // An intent with an explicitly empty route (e.g. `rental`, pending the client's
    // destination inbox) is accepted but intentionally NOT delivered anywhere yet —
    // no staff email, no confirmation, no Mailchimp. Set a recipient in email.config.ts
    // routes to activate it.
    if (!notifyTo.length) {
      return new Response(JSON.stringify({ success: true }), { status: 200 });
    }

    // Render EVERY structured answer with its real label.
    const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const detailRows = detailFields
      .map((f) =>
        `<tr><td style="padding:4px 14px 4px 0;color:#888;white-space:nowrap;vertical-align:top"><strong>${esc(f.label)}</strong></td><td style="padding:4px 0">${f.value ? esc(f.value) : '—'}</td></tr>`)
      .join('');

    // Internal notification — alerts Slack + email if the send fails (then re-throws → 500).
    // Partial leads get a distinct subject + banner so staff can chase abandoned forms.
    // The error is held rather than thrown so the Slack log below still runs;
    // it is re-thrown straight after, so the form still gets its 500.
    let notifyError: unknown = null;
    try {
      await sendWithAlert(
        {
          client: EMAIL_CONFIG.brand.name,
          formName: `${intentCfg.label}${intent ? ` (${intent})` : ''}${isPartial ? ' — partial' : ''}`,
          slackWebhookUrl: SLACK_WEBHOOK,
          alertEmail: { apiKey: import.meta.env.RESEND_API_KEY, to: EMAIL_CONFIG.alertsTo, from: EMAIL_CONFIG.from.notifications },
        },
        () => resend.emails.send({
          from:    EMAIL_CONFIG.from.notifications,
          replyTo: EMAIL_CONFIG.replyTo,
          to:      notifyTo,
          ...(notifyCc.length ? { cc: notifyCc } : {}),
          subject: isPartial ? `Started (incomplete): ${intentCfg.label} — ${company || name}` : intentCfg.notifySubject(company || name),
          html: `
            ${isPartial ? `<p style="background:#FFF4E5;border-left:3px solid #E0902F;padding:10px 14px;margin:0 0 14px;font-size:14px;color:#7a5310"><strong>⚠️ Started but not yet submitted.</strong> This person completed the contact step of the proposal form. Reach out — they may not finish on their own.</p>` : ''}
            <h2>${esc(intentCfg.label)}${isPartial ? ' (incomplete)' : ''}</h2>
            <p><strong>Name:</strong> ${esc(name)}</p>
            <p><strong>Email:</strong> ${esc(email)}</p>
            ${phone   ? `<p><strong>Phone:</strong> ${esc(phone)}</p>` : ''}
            ${company ? `<p><strong>Company:</strong> ${esc(company)}</p>` : ''}
            ${detailRows ? `<table style="border-collapse:collapse;margin:14px 0;font-size:14px">${detailRows}</table>` : ''}
            ${message ? `<p><strong>Message:</strong><br>${esc(message).replace(/\n/g, '<br>')}</p>` : ''}
            <hr><p style="color:#888;font-size:12px">${ref ? `Ref ${esc(ref)} · ` : ''}Form: ${esc(intent || 'lead')}${isPartial ? ' · stage: partial' : ''}${source ? ` · Source ${esc(source)}` : ''}</p>
          `,
        })
      );
    } catch (err) {
      notifyError = err;
    }

    // The Slack record. If the email failed, post it now (it is then the only
    // copy of the lead) and stop. Otherwise it is posted at the end, after the
    // CRM push, so one message says both "delivered" and what Pipedrive did —
    // a lead that reached the inbox but not the CRM is otherwise invisible.
    const slackRoute = `${intentCfg.label}${isPartial ? ` (started, not submitted${leadRole ? ` · ${leadRole}` : ''})` : ''}`;
    const slackForm = `${intent || 'lead'} form → ${[notifyTo].flat().join(', ')}`;
    if (notifyError) {
      await notifySubmission({
        client: EMAIL_CONFIG.brand.name,
        slackWebhookUrl: SLACK_WEBHOOK,
        route: slackRoute,
        formName: slackForm,
        delivered: false,
        fields: slackRows,
      });
      throw notifyError;
    }

    // Confirmation to submitter — only on a COMPLETE submit (don't confirm a half-finished form).
    if (!isPartial) {
      const firstName = name.split(' ')[0] || name;
      // Recap of what they submitted, so the sender can see their own answers.
      const summaryBlock = (detailRows || message)
        ? `<hr style="border:none;border-top:1px solid #e5e5ef;margin:22px 0">
           <p style="font-size:13px;color:#888;margin:0 0 8px"><strong>What you shared with us</strong></p>
           ${detailRows ? `<table style="border-collapse:collapse;font-size:14px">${detailRows}</table>` : ''}
           ${message ? `<p style="font-size:14px;margin:12px 0 0"><strong>In your words:</strong><br>${esc(message).replace(/\n/g, '<br>')}</p>` : ''}`
        : '';
      const { error: confirmError } = await resend.emails.send({
        from:    EMAIL_CONFIG.from.confirmations,
        replyTo: EMAIL_CONFIG.replyTo,
        to:      email,
        ...(EMAIL_CONFIG.bcc.length ? { bcc: EMAIL_CONFIG.bcc } : {}),
        subject: intentCfg.confirmSubject,
        html:    intentCfg.confirmBody(firstName, EMAIL_CONFIG.brand.url) + summaryBlock,
      });
      if (confirmError) console.error('Resend confirm error:', confirmError);
    }

    // Add / update the lead in Mailchimp — PROPOSAL submissions only (including
    // partial proposal captures). Vendor bids / general questions / rentals are
    // deliberately NOT synced to the audience. Upsert so a returning contact is
    // refreshed (name/company/tags) instead of erroring.
    if (intent === 'proposal') {
      await upsertMailchimpContact({
        email,
        firstName: name.split(' ')[0],
        lastName:  name.split(' ').slice(1).join(' '),
        company,
        tags: isPartial
          ? [...EMAIL_CONFIG.mailchimp.defaultTags, 'proposal-incomplete']
          : EMAIL_CONFIG.mailchimp.defaultTags,
      });
    }

    // Push PROPOSAL submissions into Pipedrive (Organization + Person + Deal).
    // Proposals only — vendor bids / general questions / rentals are not sales
    // deals, so they don't create Pipedrive records. No-op on stg/dev or until
    // PIPEDRIVE_API_TOKEN is set; never throws.
    //
    // Partials (contact step done, form not submitted) become a
    // "Started, not submitted — Name" deal so sales can chase them. When the
    // full form comes in, that partial deal is deleted and replaced by the real
    // one (see pipedrive.ts). Partials from someone who picked the resident
    // role are skipped — they're homeowners, not prospects.
    // Every answer goes into the deal's note; the ones listed in FIELD_MAP
    // (src/lib/pipedrive.ts) — "Number of units" → "Number of Homes", "Location"
    // → "Community Address" — are also written to the matching Pipedrive fields.
    const isResident = isResidentRole(leadRole);
    let crm: PipedriveOutcome | undefined;
    if (intent === 'proposal' && !(isPartial && isResident)) {
      const role = leadRole;
      // Property/community address (wizard "Location" or contact form "address")
      // → attached to the Pipedrive Organization so it shows on the Deal card.
      const address = detailFields.find((f) => /address|location/i.test(f.label))?.value || '';
      const notesText = [
        ...detailFields.map((f) => `${f.label}: ${f.value || '—'}`),
        message ? `\nMessage:\n${message}` : '',
      ].filter(Boolean).join('\n');
      crm = await addToPipedrive({
        email, name, phone, role, org: company, address,
        notes: notesText,
        fields: detailFields,
        source: `${intentCfg.label}${isPartial ? ' (started, not submitted)' : ''}${ref ? ` · ${ref}` : ''}`,
        stage: isPartial ? 'partial' : 'complete',
      });
    }

    // One Slack post per lead, stating delivery AND the CRM outcome, e.g.
    // "proposal form → newdevelopment@cmgt.org · delivered · Pipedrive: deal 891".
    // A failed CRM push is marked ⚠️ so it is not mistaken for a clean lead.
    const crmText = !crm
      ? ''
      : crm.status === 'created'
        ? `Pipedrive: ${crm.detail}`
        : crm.status === 'skipped'
          ? `Pipedrive: skipped — ${crm.detail}`
          : `Pipedrive FAILED — ${crm.detail}. The email and this channel have the lead; create the deal by hand.`;
    await notifySubmission({
      client: EMAIL_CONFIG.brand.name,
      slackWebhookUrl: SLACK_WEBHOOK,
      route: slackRoute,
      formName: slackForm,
      status: crm?.status === 'failed' ? 'warning' : 'delivered',
      ...(crmText ? { note: crmText } : {}),
      fields: slackRows,
    });

    return new Response(JSON.stringify({ success: true }), { status: 200 });
  } catch (err) {
    console.error('Lead API error:', err);
    return new Response(JSON.stringify({ error: 'Something went wrong. Please try again.' }), { status: 500 });
  }
};
